const payload = $input.first().json.body || $input.first().json;

const newVersion = payload.newVersion || payload.version || 'v2.0.0-test';
const previousVersion = payload.previousVersion || payload.baselineVersion || 'v1.9.0-test';
const appId = payload.appId || 'com.example.app';
const platform = payload.platform || 'android';

return [{
  json: {
    newVersion,
    previousVersion,
    appId,
    platform,
    currentStageIndex: 0,
    currentRolloutPercent: null
  }
}];

// Diff canary metrics against the previous version's baseline across
// crash rate, ANR rate, API error rate, and p95 latency.
const cfg = $('Set - Config').first().json;
const release = $('Code 1 - Parse Release Payload').first().json;
const all = $input.first().json;

const crashData = all.crash || all[0] || {};
const apmData = all.apm || all[1] || {};

const canaryCrashRate = Number(crashData.canary?.crashRatePercent ?? crashData.crashRatePercent ?? 0);
const baselineCrashRate = Number(crashData.baseline?.crashRatePercent ?? crashData.baselineCrashRatePercent ?? 0);
const canaryAnrRate = Number(crashData.canary?.anrRatePercent ?? crashData.anrRatePercent ?? 0);
const baselineAnrRate = Number(crashData.baseline?.anrRatePercent ?? crashData.baselineAnrRatePercent ?? 0);

const canaryErrorRate = Number(apmData.canary?.errorRatePercent ?? apmData.errorRatePercent ?? 0);
const baselineErrorRate = Number(apmData.baseline?.errorRatePercent ?? apmData.baselineErrorRatePercent ?? 0);
const canaryLatencyMs = Number(apmData.canary?.p95LatencyMs ?? apmData.p95LatencyMs ?? 0);
const baselineLatencyMs = Number(apmData.baseline?.p95LatencyMs ?? apmData.baselineP95LatencyMs ?? 0);

const crashRateDelta = Math.round((canaryCrashRate - baselineCrashRate) * 100) / 100;
const anrRateDelta = Math.round((canaryAnrRate - baselineAnrRate) * 100) / 100;
const errorRateDelta = Math.round((canaryErrorRate - baselineErrorRate) * 100) / 100;
const latencyDeltaMs = Math.round(canaryLatencyMs - baselineLatencyMs);

const thresholdBreaches = [];
if (crashRateDelta > cfg.crashRateDeltaThreshold) thresholdBreaches.push('crash_rate');
if (anrRateDelta > cfg.anrRateDeltaThreshold) thresholdBreaches.push('anr_rate');
if (errorRateDelta > cfg.errorRateDeltaThreshold) thresholdBreaches.push('api_error_rate');
if (latencyDeltaMs > cfg.latencyDeltaThresholdMs) thresholdBreaches.push('latency');

return [{
  json: {
    ...release,
    ...cfg,
    canaryCrashRate, baselineCrashRate, crashRateDelta,
    canaryAnrRate, baselineAnrRate, anrRateDelta,
    canaryErrorRate, baselineErrorRate, errorRateDelta,
    canaryLatencyMs, baselineLatencyMs, latencyDeltaMs,
    thresholdBreaches,
    rawCrashData: crashData,
    rawApmData: apmData
  }
}];

// Look for regression patterns a raw delta would miss: crashes concentrated
// on one OS version, or a single dominant crash signature.
const item = $input.first().json;
const crash = item.rawCrashData || {};
const signals = [];

const byOs = crash.crashesByOsVersion || crash.canary?.crashesByOsVersion || {};
const totalCrashes = Object.values(byOs).reduce((s, v) => s + Number(v || 0), 0);
for (const [osVersion, count] of Object.entries(byOs)) {
  if (totalCrashes > 0 && (Number(count) / totalCrashes) > 0.6) {
    signals.push({
      type: 'concentrated_os_regression',
      osVersion,
      sharePercent: Math.round((Number(count) / totalCrashes) * 100),
      note: 'Over 60% of new crashes are concentrated on a single OS version - likely an OS-specific regression rather than a general rollout risk.'
    });
  }
}

const topSignature = crash.topCrashSignature || crash.canary?.topCrashSignature;
if (topSignature && item.crashRateDelta > 0) {
  signals.push({
    type: 'dominant_crash_signature',
    signature: topSignature,
    note: 'A single crash signature is driving the elevated crash rate - worth triaging before deciding.'
  });
}

return [{
  json: {
    ...item,
    regressionSignals: signals,
    regressionSignalCount: signals.length
  }
}];

const aiResponse = $input.first().json;
const item = $('Code 3 - Detect Correlated Regression Signals').first().json;

let rec;
try {
  const rawText = aiResponse.content?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  rec = JSON.parse(cleaned);
} catch (e) {
  rec = { recommendation: 'pause', confidenceScore: 0, reasoning: 'Unable to parse AI response', riskSummary: '' };
}

// Safety override: force rollback on severe crash/ANR regression regardless of what the AI recommends
const SEVERE_MULTIPLIER = 2;
const severeBreach = item.crashRateDelta > (item.crashRateDeltaThreshold * SEVERE_MULTIPLIER)
  || item.anrRateDelta > (item.anrRateDeltaThreshold * SEVERE_MULTIPLIER);

let finalRecommendation = rec.recommendation || 'pause';
if (severeBreach) finalRecommendation = 'rollback';

return [{
  json: {
    ...item,
    aiRecommendation: rec.recommendation,
    confidenceScore: rec.confidenceScore ?? 0,
    reasoning: rec.reasoning || '',
    riskSummary: rec.riskSummary || '',
    severeBreach,
    finalRecommendation
  }
}];

const item = $input.first().json;
const stages = (item.rolloutStages || '5,25,50,100').split(',').map(s => Number(s.trim()));
const nextIndex = (item.currentStageIndex ?? 0) + 1;
const nextPercent = stages[Math.min(nextIndex, stages.length - 1)];
const rolloutComplete = nextPercent >= 100;

return [{
  json: {
    ...item,
    currentStageIndex: nextIndex,
    currentRolloutPercent: nextPercent,
    rolloutComplete
  }
}];

